import math
import time
from collections import deque
from typing import Dict, List, Optional, Tuple, Any

class EntropyChurnDefense:
    """Calculates sliding-window entropy over incoming peer message metadata
    to detect and penalize Sybil nodes flooding fake heartbeat vectors.
    """
    def __init__(self, window_size: int = 50, entropy_threshold: float = 1.2, max_ticks_to_drop: int = 3):
        self.window_size = window_size
        self.entropy_threshold = entropy_threshold
        self.max_ticks_to_drop = max_ticks_to_drop
        # node_id -> deque of metadata feature values or timestamps/tokens
        self.peer_windows: Dict[str, deque] = {}
        # node_id -> tick count of anomalous variance
        self.violation_counts: Dict[str, int] = {}
        # quarantined/dropped nodes
        self.quarantined_peers: set = set()

    def record_message(self, node_id: str, metadata_feature: float) -> None:
        """Records a feature value from a peer's message metadata into a bounded deque."""
        if node_id in self.quarantined_peers:
            return
        if node_id not in self.peer_windows:
            self.peer_windows[node_id] = deque(maxlen=self.window_size)
        self.peer_windows[node_id].append(metadata_feature)

    def calculate_entropy(self, values: List[float]) -> float:
        """Calculates Shannon entropy over discretized feature values."""
        if not values:
            return 0.0

        # Discretize continuous values into bins or frequency counts
        counts: Dict[Any, int] = {}
        total = len(values)
        for val in values:
            # Round to 2 decimal places to form discrete buckets
            bucket = round(float(val), 2)
            counts[bucket] = counts.get(bucket, 0) + 1

        entropy = 0.0
        for count in counts.values():
            prob = count / total
            if prob > 0:
                entropy -= prob * math.log2(prob)
        return entropy

    def evaluate_peer(self, node_id: str) -> bool:
        """Evaluates a peer's recent message entropy against the threshold.
        Returns True if the peer is flagged as a Sybil/abnormal node and should be dropped.
        """
        if node_id in self.quarantined_peers:
            return True

        window = self.peer_windows.get(node_id)
        if not window or len(window) < 5:
            return False

        ent = self.calculate_entropy(list(window))

        # Sybil detectors look for either abnormally low entropy (robotic flooding)
        # or abnormally high entropy (randomized fake noise vectors).
        if ent < 0.3 or ent > self.entropy_threshold:
            violations = self.violation_counts.get(node_id, 0) + 1
            self.violation_counts[node_id] = violations
            if violations >= self.max_ticks_to_drop:
                self.quarantined_peers.add(node_id)
                return True
        else:
            # Decay violation count on normal tick
            if node_id in self.violation_counts:
                self.violation_counts[node_id] = max(0, self.violation_counts[node_id] - 1)

        return False

    def is_quarantined(self, node_id: str) -> bool:
        return node_id in self.quarantined_peers

import os
import json
import time
import uuid
from collections import deque
from enum import Enum
from pathlib import Path
from typing import Callable, Dict, List, Optional, Any

from gossipmesh.p2p.churn import EntropyChurnDefense

class GossipTopic(str, Enum):
    CODE_REVIEW = "code_review"
    SECURITY_ALERT = "security_alert"
    AGENT_SYNC = "agent_sync"
    HEARTBEAT = "heartbeat"

class GossipMessage:
    def __init__(
        self,
        topic: str,
        origin_node: str,
        payload: Dict[str, Any],
        repo: str = "global",
        message_id: Optional[str] = None,
        vector_clock: Optional[Dict[str, int]] = None,
        timestamp: Optional[float] = None,
        ttl: int = 10,
    ):
        self.topic = topic
        self.origin_node = origin_node
        self.payload = payload
        self.repo = repo
        self.message_id = message_id or str(uuid.uuid4())
        self.vector_clock = vector_clock or {}
        self.timestamp = timestamp or time.time()
        self.ttl = ttl

    def to_dict(self) -> Dict[str, Any]:
        return {
            "message_id": self.message_id,
            "topic": self.topic,
            "origin_node": self.origin_node,
            "payload": self.payload,
            "repo": self.repo,
            "vector_clock": self.vector_clock,
            "timestamp": self.timestamp,
            "ttl": self.ttl,
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> 'GossipMessage':
        return cls(
            topic=data.get("topic", GossipTopic.AGENT_SYNC),
            origin_node=data.get("origin_node", "unknown"),
            payload=data.get("payload", {}),
            repo=data.get("repo", "global"),
            message_id=data.get("message_id"),
            vector_clock=data.get("vector_clock", {}),
            timestamp=data.get("timestamp"),
            ttl=data.get("ttl", 10),
        )

class GossipNode:
    """Decentralized Gossip Peer Node with Entropy-Based Churn Defense."""
    def __init__(self, node_id: str, mesh_dir: str | None = None):
        self.node_id = node_id
        self.mesh_dir = Path(mesh_dir) if mesh_dir else Path(".gossip_mesh/ledger")
        self.mesh_dir.mkdir(parents=True, exist_ok=True)
        self.subscribers: Dict[str, List[Callable[[GossipMessage], None]]] = {}
        self.seen_messages: set = set()
        self.message_cache: deque = deque(maxlen=1000)
        self.churn_defense = EntropyChurnDefense()
        self._load_seen_history()

    def _load_seen_history(self):
        if not self.mesh_dir.exists():
            return
        for file_path in self.mesh_dir.glob("*.json"):
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    data = json.load(f);
                    mid = data.get("message_id")
                    if mid:
                        self.seen_messages.add(mid)
            except Exception:
                continue

    def subscribe(self, topic: GossipTopic, handler: Callable[[GossipMessage], None]):
        if topic not in self.subscribers:
            self.subscribers[topic] = []
        self.subscribers[topic].append(handler)

    def publish(self, topic: GossipTopic, payload: Dict[str, Any], repo: str = "global", ttl: int = 10) -> GossipMessage:
        msg = GossipMessage(
            topic=topic,
            origin_node=self.node_id,
            payload=payload,
            repo=repo,
            ttl=ttl
        )
        self.seen_messages.add(msg.message_id)
        self.message_cache.append(msg)

        ledger_file = self.mesh_dir / f"{msg.message_id}.json"
        with open(ledger_file, "w", encoding="utf-8") as f:
            json.dump(msg.to_dict(), f)

        return msg

    def ingest_message(self, msg: GossipMessage) -> bool:
        """Ingests an incoming peer message, passing metadata to entropy churn defense."""
        if self.churn_defense.is_quarantined(msg.origin_node):
            return False

        # Extract feature (e.g. timestamp mod or payload size/hash)
        feature = float(msg.timestamp % 60)
        self.churn_defense.record_message(msg.origin_node, feature)

        if self.churn_defense.evaluate_peer(msg.origin_node):
            return False

        if msg.message_id in self.seen_messages:
            return False

        self.seen_messages.add(msg.message_id)
        self.message_cache.append(msg)
        return True

    def sync(self) -> List[GossipMessage]:
        new_messages = []
        if not self.mesh_dir.exists():
            return new_messages

        for file_path in self.mesh_dir.glob("*.json"):
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                    msg = GossipMessage.from_dict(data)
                    if msg.origin_node != self.node_id:
                        if self.ingest_message(msg):
                            new_messages.append(msg)
            except Exception:
                continue
        return new_messages

    def heartbeat(self):
        self.publish(GossipTopic.HEARTBEAT, {"status": "alive", "time": time.time()})

    def get_recent_messages(self, topic: Optional[GossipTopic] = None, limit: int = 50) -> List[GossipMessage] :
        msgs = list(self.message_cache)
        if topic:
            msgs = [m for m in msgs if m.topic == topic]
        return msgs[-limit:]

    def cleanup_ledger(self):
        if not self.mesh_dir.exists():
            return
        now = time.time()
        for file_path in self.mesh_dir.glob("*.json"):
            try:
                with open(file_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                    ts = data.get("timestamp", now)
                    ttl = data.get("ttl", 10)
                    if now - ts > ttl * 60:
                        file_path.unlink(missing_ok=True)
            except Exception:
                continue
